<?php
require_once __DIR__.'/../config/session.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/helper.php';require_once __DIR__.'/../config/auth.php';check_access([3]);
$db=Database::getInstance();
$stmt=$db->prepare("SELECT s.id,s.nama_lengkap,s.nis,s.nisn,k.nama_kelas,k.tingkat,COALESCE(t.target_poin,0) target_poin FROM siswa s LEFT JOIN kelas k ON k.id=s.kelas_id LEFT JOIN kak_target_tingkat t ON t.tingkat=k.tingkat WHERE s.user_id=?");$stmt->execute([$_SESSION['user_id']]);$siswa=$stmt->fetch();if(!$siswa){http_response_code(404);exit('Data siswa tidak ditemukan.');}
$stmt=$db->prepare("SELECT a.nama_aktivitas,a.keterangan,a.tanggal_aktivitas,a.poin,g.nama_lengkap nama_guru FROM kak_aktivitas_siswa a JOIN guru g ON g.id=a.guru_id WHERE a.siswa_id=? ORDER BY a.tanggal_aktivitas DESC,a.id DESC");$stmt->execute([(int)$siswa['id']]);$riwayat=$stmt->fetchAll();
$total_poin=array_sum(array_map(static fn($item)=>(int)$item['poin'],$riwayat));$target_poin=(int)$siswa['target_poin'];$kekurangan=max(0,$target_poin-$total_poin);$tercapai=$target_poin>0&&$total_poin>=$target_poin;$persentase=$target_poin>0?min(100,(int)round($total_poin/$target_poin*100)):0;
?>
<?php require_once __DIR__.'/../includes/header.php';?><?php require_once __DIR__.'/../includes/sidebar.php';?>
