<div id="page-content-wrapper" class="kak-page"><nav class="navbar top-navbar px-3 px-md-4 py-3"><div><h5 class="fw-bold mb-0"><i class="fa-solid fa-medal text-warning me-2"></i>Kredit Aktivitas Siswa</h5><small class="text-muted"><?=sanitize(($siswa['nama_kelas']?:'Kelas belum ditentukan').' · Tingkat '.($siswa['tingkat']?:'-'))?></small></div></nav><main class="kak-main p-3 p-md-4">
<section class="card kak-card kak-summary mb-3"><div class="card-body p-4"><div class="row g-4 align-items-center"><div class="col-md-7"><small class="opacity-75">Total poin Kredit Aktivitas Siswa</small><div class="kak-number fw-bold my-2"><?=$total_poin?></div><div class="opacity-75">Target tingkat <?=sanitize($siswa['tingkat']?:'-')?>: <strong><?=$target_poin?> poin</strong></div></div><div class="col-md-5"><div class="d-flex justify-content-between small mb-2"><span>Pencapaian</span><strong><?=$persentase?>%</strong></div><div class="progress kak-progress mb-3" role="progressbar" aria-valuenow="<?=$persentase?>" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:<?=$persentase?>%"></div></div><?php if($target_poin===0):?><span class="badge bg-light text-dark">Target belum ditetapkan sekolah</span><?php elseif($tercapai):?><span class="badge bg-success"><i class="fa-solid fa-circle-check me-1"></i>Target tercapai</span><?php else:?><span class="badge bg-warning text-dark">Kurang <?=$kekurangan?> poin lagi</span><?php endif;?></div></div></div></section>
<section class="card kak-card"><div class="card-body p-3 p-md-4"><div class="d-flex justify-content-between align-items-center mb-2"><h2 class="h6 fw-bold mb-0">Riwayat Aktivitas</h2><span class="badge bg-primary-subtle text-primary"><?=count($riwayat)?> aktivitas</span></div><?php if(!$riwayat):?><div class="text-center py-5"><i class="fa-solid fa-award fa-2x text-secondary mb-3"></i><p class="text-muted mb-0">Belum ada aktivitas yang diberi poin oleh guru.</p></div><?php else:foreach($riwayat as $item):?><article class="activity-row"><div class="activity-points">+<?=(int)$item['poin']?><small class="d-block fw-normal">poin</small></div><div class="activity-copy"><strong class="d-block"><?=sanitize($item['nama_aktivitas'])?></strong><small class="text-muted"><i class="fa-regular fa-calendar me-1"></i><?=date('d M Y',strtotime($item['tanggal_aktivitas']))?> · diberikan oleh <?=sanitize($item['nama_guru'])?></small><?php if($item['keterangan']):?><p class="small text-secondary mb-0 mt-2"><?=nl2br(sanitize($item['keterangan']))?></p><?php endif;?></div></article><?php endforeach;endif;?></div></section>
</main></div><?php require_once __DIR__.'/../includes/footer.php';?>
